#!/usr/bin/env python3
"""Audit the texts/ folder: what is there, whether it is what it says it is, how clean it is, and what the Library and the Atlas catalogue list that is not there.

Reads (nothing is changed):  ../texts/*.js, the Library list in src/js/24-data-path-lib.js, the Atlas catalogue in ../atlas/texts.js
Writes:                      ../TEXT_AUDIT.md (the report) and ../TEXT_GAPS.csv (every Atlas text record, with whether it is in the folder)
Run from lamplighter/:           python3 -I tools/audit_texts.py          (needs node, for the two JavaScript data files)
"""
import csv, hashlib, json, os, re, subprocess, sys, collections

HERE = os.path.dirname(os.path.abspath(__file__)); BEAT = os.path.dirname(HERE); ROOT = os.path.dirname(BEAT)
TEXTS = os.path.join(ROOT, 'texts'); ATLAS = os.path.join(ROOT, 'atlas'); SRC = os.path.join(HERE, 'atlas_src', 'json')

# ── loading ──
def load_text(path):
    s = open(path, encoding='utf-8').read(); dec = json.JSONDecoder(); i = len('BEATLAB_TEXTS.add(')
    def skip(i):
        while s[i] in ' \n,': i += 1
        return i
    tid, i = dec.raw_decode(s, i); i = skip(i); meta, i = dec.raw_decode(s, i); i = skip(i); secs, i = dec.raw_decode(s, i)
    return tid, meta, secs

def node_json(js):
    out = subprocess.run(['node', '-e', js], capture_output=True, text=True, check=True).stdout
    return json.loads(out)

LIB = node_json("const L=require(%r);console.log(JSON.stringify(L.LIB))" % os.path.join(BEAT, 'src/js/24-data-path-lib.js'))
ATL = node_json("""const fs=require('fs'),vm=require('vm');globalThis.BEATLAB_ATLAS={data:{},add(n,d){this.data[n]=d}};
for(const n of ['index','core','texts']) vm.runInThisContext(fs.readFileSync(%r+'/'+n+'.js','utf8'));
const D=BEATLAB_ATLAS.data;console.log(JSON.stringify({texts:D.texts,trad:D.core.traditions.map(t=>({id:t.id,name:t.name,family_id:t.family_id,kind:t.kind})),groups:D.index.config.family_groups.groups,codes:D.index.codes}))""" % ATLAS)
LIBBY = {l['id']: l for l in LIB}

texts = {}
for f in sorted(os.listdir(TEXTS)):
    if not re.match(r'^[a-z]-.+\.js$', f): continue
    tid, meta, secs = load_text(os.path.join(TEXTS, f)); texts[tid] = (meta, secs)

# ── helpers ──
WORDS = set(w.strip().lower() for w in open('/usr/share/dict/words', encoding='utf-8', errors='ignore')) if os.path.exists('/usr/share/dict/words') else set()
COMMON = set('the of and to in is that it for as with was he his be by on not or are this from at which but have an had they you were their one all we can her has there been if more when will would who so no she him do into than its our then them these two may first any my such like other what up out about only your how said did down could after also over new should even most made before must through between much where both being those while still every again because here under without against same since however thus whom whose'.split())
SUFFIX = ('s', 'es', 'ed', 'd', 'ing', 'ly', 'er', 'est', 'ness', 'ful', 'less', 'ment', 'ings', 'ers')
def known(w):
    if w in WORDS or w in COMMON: return True
    for sfx in SUFFIX:
        if w.endswith(sfx) and len(w) - len(sfx) >= 3:
            b = w[:-len(sfx)]
            if b in WORDS or b + 'e' in WORDS or (len(b) > 3 and b[-1] == b[-2] and b[:-1] in WORDS): return True
    return False
TOK = re.compile(r"[A-Za-z]{3,}")
def dict_score(s):
    t = TOK.findall(s)
    if not t: return 0.0
    k = sum(1 for w in t if known(w.lower()))
    return k / len(t)
JUNK = re.compile(r"[^\w\s.,;:!?'’‘“”\"()\[\]\-–—/&·*]", re.U)
def junk_ratio(s): return len(JUNK.findall(s)) / max(1, len(s))

# ── per text ──
rows = {}; by_hash = collections.defaultdict(list); sec_hash = collections.defaultdict(set)
for tid, (meta, secs) in texts.items():
    body = [b for _, b in secs]; full = '\n'.join(body); chars = sum(len(b) for b in body)
    h = hashlib.sha1(full.encode('utf-8')).hexdigest(); by_hash[h].append(tid)
    for _, b in secs:
        if len(b) > 400: sec_hash[hashlib.sha1(b.strip().encode('utf-8')).hexdigest()].add(tid)
    scan = 'scan of an edition' in meta.get('license', '')
    r = dict(id=tid, title=meta['title'], by=meta.get('by', ''), license=meta.get('license', ''), n=len(secs), chars=chars, meta_n=meta.get('n'), meta_chars=meta.get('chars'), scan=scan, junk=junk_ratio(full[:2000000]),
             gut=('Project Gutenberg' in full or 'START OF THE PROJECT' in full or 'END OF THE PROJECT' in full), hash=h)
    if scan:
        sample = full if chars < 3000000 else full[:1500000] + full[chars // 2: chars // 2 + 1500000]
        r['score'] = dict_score(sample)
        sc = [dict_score(b) for _, b in secs if len(b) > 1500]; r['secs_bad'] = sum(1 for x in sc if x < 0.45); r['secs_n'] = len(sc)
        r['first_bad'] = bool(secs) and dict_score(secs[0][1][:6000]) < 0.45
        r['first_title'] = secs[0][0][:60] if secs else ''
    stamp = re.search(r'GOVERNMENT OF INDIA|ACCESSION NO|CENTRAL\s+ARCH|Return this material|Library Regr|PLEASE DO NOT REMOVE|BINDING SECT|SOUTHERN REGIONAL LIBRARY', full[:3000] + full[-3000:])
    r['stamp'] = stamp.group(0) if stamp else ''
    def index_like(b):
        ls = [l for l in b.split('\n') if l.strip()]
        if len(ls) < 15: return False
        hit = sum(1 for l in ls if len(l) < 110 and re.search(r'\d+\s*(?:,|;|–|-)\s*\d+|\bsee\b.*\d|,\s*\d+\s*$', l))
        return hit / len(ls) > 0.45
    head_idx = lambda b: bool(re.search(r'(?im)^(?:GENERAL |ALPHABETICAL )?INDEX\b', b)); r['idx_first'] = bool(secs) and index_like(secs[0][1]) and head_idx(secs[0][1]); r['idx_last'] = bool(secs) and index_like(secs[-1][1]) and head_idx(secs[-1][1]); r['idx_n'] = sum(1 for _, b in secs if index_like(b))
    rows[tid] = r
clean = [dict_score(texts[t][1][0][1][:200000]) for t in ('b-gen', 'n-joh', 'x-dhp', 'x-ana') if t in texts]
baseline = sum(clean) / len(clean) if clean else 0

dups = [v for v in by_hash.values() if len(v) > 1]
share = collections.defaultdict(int)
for h, ts in sec_hash.items():
    if len(ts) > 1:
        for a in ts:
            for b in ts:
                if a < b: share[(a, b)] += 1
shared = sorted(((n, a, b) for (a, b), n in share.items() if n >= 3), reverse=True)

# ── structure: the Bible ──
BIBLE = {'gen': 50, 'exo': 40, 'lev': 27, 'num': 36, 'deu': 34, 'jos': 24, 'jdg': 21, 'rut': 4, '1sa': 31, '2sa': 24, '1ki': 22, '2ki': 25, '1ch': 29, '2ch': 36, 'ezr': 10, 'neh': 13, 'est': 10, 'job': 42, 'psa': 150, 'pro': 31, 'ecc': 12, 'sos': 8, 'isa': 66, 'jer': 52, 'lam': 5, 'eze': 48, 'dan': 12, 'hos': 14, 'joe': 3, 'amo': 9, 'oba': 1, 'jon': 4, 'mic': 7, 'nah': 3, 'hab': 3, 'zep': 3, 'hag': 2, 'zec': 14, 'mal': 4}
NT = {'mat': 28, 'mar': 16, 'luk': 24, 'joh': 21, 'act': 28, 'rom': 16, '1co': 16, '2co': 13, 'gal': 6, 'eph': 6, 'php': 4, 'col': 4, '1th': 5, '2th': 3, '1ti': 6, '2ti': 4, 'tit': 3, 'phm': 1, 'heb': 13, 'jas': 5, '1pe': 5, '2pe': 3, '1jo': 5, '2jo': 1, '3jo': 1, 'jud': 1, 'rev': 22}
bible_issues = []; verses_total = {'OT': 0, 'NT': 0}; bible_found = 0
for pre, table, tag in (('b-', BIBLE, 'OT'), ('n-', NT, 'NT')):
    for k, nch in table.items():
        tid = pre + k
        if tid not in texts: bible_issues.append('%s is not in the folder' % tid); continue
        bible_found += 1; secs = texts[tid][1]
        if len(secs) != nch: bible_issues.append('%s has %d chapters, expected %d' % (tid, len(secs), nch))
        for ci, (ct, b) in enumerate(secs, 1):
            vs = [int(x) for x in re.findall(r'\[\[(\d+)\]\]', b)]; verses_total[tag] += len(vs)
            if not vs: bible_issues.append('%s chapter %d has no verse numbers' % (tid, ci)); continue
            if vs[0] != 1 or any(vs[i + 1] - vs[i] not in (1, 0) and not (vs[i + 1] > vs[i]) for i in range(len(vs) - 1)): bible_issues.append('%s chapter %d: verse numbers run %s' % (tid, ci, vs[:6]))
            elif any(vs[i + 1] != vs[i] + 1 for i in range(len(vs) - 1)): bible_issues.append('%s chapter %d: a verse number is skipped (%s)' % (tid, ci, [vs[i] for i in range(len(vs) - 1) if vs[i + 1] != vs[i] + 1][:3]))
quran_n = len(texts['x-qur'][1]) if 'x-qur' in texts else 0

# ── the Atlas catalogue against the folder ──
codes = ATL['codes']; fam_group = {f: g['id'] for g in ATL['groups'] for f in g['families']}; group_name = {g['id']: g['label'] for g in ATL['groups']}
trad = {t['id']: t for t in ATL['trad']}; status_names = codes.get('text_status') or codes.get('status') or {}
cov = []
for x in ATL['texts']:
    t = trad.get(x.get('tradition_id')) or {}; lib = x.get('lib') or ''; libs = x.get('libs') or ([lib] if lib else []); part = bool(x.get('libp'))
    cov.append(dict(id=x['id'], title=x['title'], tradition=t.get('name', ''), family=t.get('family_id', ''), group=group_name.get(fam_group.get(t.get('family_id', ''), ''), ''), date=x.get('date_label', ''), year=x.get('year_start'), status=x.get('status', ''),
                    category=x.get('category', ''), language=x.get('language', ''), lib=' + '.join(libs), in_folder=('yes (several files)' if len(libs) > 1 and all(i in texts for i in libs) else ('yes (part of the work)' if lib in texts and part else ('yes' if lib in texts else ('library entry, no file' if lib else 'no')))), note=(x.get('note') or '')[:200]))
with open(os.path.join(ROOT, 'TEXT_GAPS.csv'), 'w', newline='', encoding='utf-8') as fh:
    w = csv.DictWriter(fh, fieldnames=list(cov[0].keys())); w.writeheader(); w.writerows(cov)
cnt = collections.Counter(c['in_folder'] for c in cov); cov_yes = sum(v for k, v in cnt.items() if k.startswith('yes')); st = collections.Counter(c['status'] for c in cov)
by_group = collections.defaultdict(lambda: collections.Counter())
for c in cov:
    by_group[c['group']]['records'] += 1; by_group[c['group']][c['in_folder']] += 1; by_group[c['group']]['status:' + c['status']] += 1
lib_ids_in_atlas = {c['lib'] for c in cov if c['lib']}
lib_missing = [l for l in LIB if l['id'] not in texts]; lib_missing_g = collections.Counter(l['group'] for l in lib_missing)

# ── the report ──
def md_table(head, rows_):
    return '\n'.join(['| ' + ' | '.join(head) + ' |', '|' + '---|' * len(head)] + ['| ' + ' | '.join(str(c) for c in r) + ' |' for r in rows_])
L = []; A = L.append
nscan = sum(1 for r in rows.values() if r['scan'])
A('# Texts audit\n')
A('Generated by `lamplighter/tools/audit_texts.py`, which only reads `texts/` and changes nothing. Every number below is computed from the files, not estimated; the “What the audit found” block is written by hand.\n')
A('## At a glance\n')
A('* **%d texts** are in the folder, **%s MB** of text. The Library lists **%d** entries; **%d** are in the folder, **%d** are not (see below).' % (len(texts), '{:.1f}'.format(sum(r['chars'] for r in rows.values()) / 1e6), len(LIB), len(LIB) - len(lib_missing), len(lib_missing)))
A('* The Atlas catalogue lists **%d** text records. **%d** are covered by a text in the folder (%d fully, %d only in part, %d by several files), **%d** match a Library entry with no file, and **%d** match nothing. Matches are the exact or near title plus a hand-checked list (`tools/atlas_text_aliases.json`); the CSV shows each one.' % (len(cov), cov_yes, cnt['yes'], cnt['yes (part of the work)'], cnt['yes (several files)'], cnt['library entry, no file'], cnt['no']))
A('* **%d** of the %d files come from scans (OCR), the rest from Project Gutenberg, the World English Bible and SuttaCentral. Scans can carry recognition errors.' % (nscan, len(texts)))
A('* Every file’s section count and size agree with its own header: **%s**.' % ('yes' if all(r['meta_n'] == r['n'] and abs((r['meta_chars'] or 0) - r['chars']) < 5 for r in rows.values()) else 'NO, see below'))
A('* The Bible books (39 Old Testament, 27 New Testament, WEB): **%d of 66 present, %s**. Verses counted: %d Old Testament, %d New Testament. The Qur’an has **%d** suras.\n' % (bible_found, 'all with the right chapter count and consecutive verse numbers' if not bible_issues else '%d problems (listed below)' % len(bible_issues), verses_total['OT'], verses_total['NT'], quran_n))
A('## What the audit found, and what has been done about it (reviewed by hand)\n')
A('**Fixed.** Corrected sources were fetched from archive.org (the Sacred Books of the East volumes named in `tools/texts_archive.py`) and the entries rebuilt by the builder, not by hand:\n')
A('1. **Heart Sūtra and Diamond Sūtra** were both Cowell’s *Buddhacarita* (SBE 49 part 1). They now hold the sutras: the Heart Sūtra in both versions and the Diamond-cutter with Müller’s introduction (SBE 49 part 2, 1894). The Buddhacarita is its own entry (`x-bud`), and the Larger and Smaller Sukhāvatī-vyūha and the Amitāyur-dhyāna-sūtra from the same volume are new entries (`x-slv`, `x-sms`, `x-amd`).')
A('2. **The Upanishads.** The Library title promised the Brihadaranyaka and Chandogya but the file held three Upanishads. Twelve of Müller’s translations are now their own entries (Chandogya, Brihadaranyaka, Taittiriya, Aitareya Aranyaka, Kaushitaki, Isha, Katha, Kena, Mundaka, Shvetashvatara, Prashna, Maitri); `x-upa` is retitled and its note corrected to say it is Paramananda’s Isha, Katha and Kena. The Mandukya is in neither translation; it was added separately (item 6).')
A('3. **Files that were one volume under two names** are now cut apart: Acaranga and Kalpa Sūtras (`x-aca`, `x-kalp`), Odes and Psalms of Solomon (`p-ode`, `p-pss`), Great Learning with the Doctrine of the Mean and Mencius (`x-gl`, `x-men`; the Analects were already separate).')
A('4. **Titles now say what is inside** for the Upanishads, Vishnu Purana, Guru Granth Sahib (Macauliffe), Khuddaka Nikaya, Abhidhamma, Shatapatha Brahmana, Milarepa, Orphic Hymns, Book of Documents and al-Ghazali. `x-ghaz` is Claud Field’s *Alchemy of Happiness*, not the *Revival*.')
A('5. **Debris removed by the builder:** the Indian library accession page and the series advertisements (`x-ghaz`), the museum bulletin’s catalogue and library rules (`x-glp`), the publisher’s lists and stamps before the Preface (`x-keb`), stray cover lines (`x-bhagat`, `x-jap`), Project Gutenberg’s file header and footer lines (`x-ana`, `x-bod`, `x-can`, `x-shy`), library slips glued to the end of scans, and back-of-book indexes at the end of `e-sayings`, `x-gar`, `x-ath`, `x-sam`, `x-keb` and `x-glp`.\n')
A('6. **The Jātaka and the Mandukya Upanishad were added** (second round, from sources listed to the user and approved first). `x-jat` is Cowell’s six-volume Cambridge translation of the Jātaka commentary, all 547 tales in the 22 books, from six archive.org scans (the Cambridge University Press edition, 1895–1907; volume IV is the Digital Library of India’s scan); each volume’s preface is kept, its contents list and index are left out, and about 850 running heads were stripped by the builder. `x-mdk` is Dvivedi’s 1894 translation of the Mandukya Upanishad with Gaudapāda’s Kārikās and Śaṅkara’s commentary, with his preface and introduction and the glossary of Sanskrit terms. Of the 547 tale headings (“No. 1.”), 515 were read cleanly by the scan; the other 32 are OCR-damaged but their text is in place. Scan quality is 0.94 (`x-jat`) and 0.92 (`x-mdk`) by the dictionary measure used below.')
A('7. **Ten freedom-of-conscience texts were added** (third round, from sources listed to the user and approved first), built by `tools/texts_freedom.py` and not scans: Roger Williams’s *Bloudy Tenent* (`f-blt`, Project Gutenberg #65739, the 1848 edition, 173 sections), Spinoza’s *Theological-Political Treatise* in Elwes’s translation (`f-spi`, Gutenberg #989–992), Madison’s *Memorial and Remonstrance* (`f-mem`, the University of Chicago’s *Founders’ Constitution*, added a day later), Locke’s *Letter Concerning Toleration* (`f-lok`, Wikisource), the Cyrus Cylinder in Rogers’s 1912 translation (`f-cyr`, an older revision of a Wikisource page, because its current text is a different translation) and Smith’s *Edicts of Asoka* (`f-ash`, OCR of a scan at the Internet Archive, cleaned by machine, so misreadings remain; both added on 16 November), Mill’s *On Liberty* (`f-mil`, #34901), the Virginia Statute (`f-vst`, Code of Virginia § 57-1), the Bill of Rights (`f-bor`, National Archives) and the Universal Declaration of Human Rights (`f-udh`, un.org). Left out of the books: the editors’ introductions and footnotes, the printed side-notes, the e-texts’ tables of contents, search strings and sentence numbers (each entry’s note says so); kept: Mill’s and Spinoza’s own notes and the editor’s bracketed insertions in Williams. `f-udh` is a United Nations document under the UN’s own terms of use, not public domain or CC0, and its licence line says so. `f-mem`’s licence line says that its source page is marked © 1987 University of Chicago while Madison’s own words are public domain. `tests/freedom-texts.test.js` checks all ten.')
A('8. **The Puggalapaññatti was added** (from a source listed to the user and approved first). `x-pug` is Bimala Charan Law’s 1924 Pali Text Society translation, *Designation of Human Types*, the fourth book of the Abhidhamma Pitaka, from the Internet Archive scan of the Oxford University Press edition. It has Law’s introduction (to his dated signature), the opening homage and Table of Contents of the work, and all ten chapters, the groupings of persons by ones up to tens; the page-number index is left out and the footnotes are run into the text where the page broke. The edition is public domain in the United States (published 1924), but the translator died in 1969, so it may still be protected in other countries, and the entry’s note says so. Scan quality is 0.96 by the dictionary measure used below.')
A('9. **Many more open translations were added** (16 November 2026, on the maker’s instruction “find everything you can and get them all”): 163 texts, 228 MB of text files in all (counting Law’s Puggalapaññatti and Sinha’s Bhagavata study), found by searching the Internet Archive and Project Gutenberg and built by `tools/texts_shelf.py`, `texts_more.py`, `texts_fathers.py` and `texts_talmud.py`. **The Library’s six shelves** (Hermetic and alchemical, ceremonial magic, Spiritualism and Theosophy, Freemasonry, Siberia and the Arctic, tribal field records): 53 texts. **The Sacred Books of the East volumes the Library lacked:** the Dharmasūtras (`x-sac`), Manu (`x-lom`), the Viṣṇu and Nārada law books, the Gṛihya Sūtras, the Vedic Hymns (`x-vhy`) and Atharva-Veda (`x-abv`), the Vedānta-sūtras with Śaṅkara’s and Rāmānuja’s commentaries, Telang’s Gita, the Buddhist Suttas, the Vinaya, the Buddhacarita from the Chinese, Kern’s Lotus, the Milindapañha, four Pahlavi volumes, the Li Ki, the Texts of Taoism and Palmer’s Qur’an. **The Puranas:** the Bhāgavata in Subba Rau’s full prose (`x-bhs`) beside Sinha’s 1901 study (`x-bhp`), the Devī Bhāgavata, Mārkaṇḍeya with the Devī Māhātmya, Matsya, Agni, Garuda and the first half of the Brahma-Vaivarta. **Philosophy and devotion:** the Mīmāṃsā, Vaiśeṣika and Sāṃkhya sūtras, the Nārada Bhakti Sūtras, Woods’s Yoga, Tulsidas’s Rāmāyaṇa, the Tiruvāçagam and the Nāladiyār. **Pali and Buddhist:** Burlingame’s Buddhist Legends, the Mahāvaṃsa, Dīpavaṃsa, the Expositor, the Compendium of Philosophy, the Udāna, part one of the Path of Purity, Warren’s Buddhism in Translations, and second translations of the Dīgha, Majjhima and Therī- and Theragāthā (Rhys Davids, Chalmers). **Other:** Pickthall’s and Sale’s Qur’ans, Trumpp’s Ādi Granth, Hujwiri, Sa‘dī, Attar (abridged) and Rabia, the Chaldean Account of Genesis and Amenemope, the Books of Adam and Eve, 3 and 4 Baruch and the Forgotten Books of Eden. **The Church Fathers:** 33 volumes (the Nicene and Post-Nicene Fathers, first series volumes 1–14 and second series volumes 1–6 and 8–14, and the Ante-Nicene Fathers volumes 2, 4, 5, 6, 8 and 9). **The Talmud:** Rodkinson’s English tractates (14 entries: twenty-four tractates, Eduyoth and Aboth with the Mishnah only, and his History of the Talmud). Each tractate is cut out of its scan once; several scans bind two or three volumes, and a first version of these entries repeated tractates until the main session’s overlap check caught it. **How these were built:** generically. A printed index is cut from the back and the title pages from the front, headings come from the book’s own BOOK, CHAPTER or PART lines where it has four or more, and otherwise the text is chunked; so section titles are less tidy than in the hand-sliced texts, and a volume’s contents list often stays at its start. **What is rough:** the three seventeenth-century scans in long-s type (`h-fama`, `h-chym`, `m-hept`) read poorly even after the spelling repair, and `h-dee`, `m-agr4` and `x-sen` read better but not well; Abramelin (`m-abra`) is Book II only; the Devī Bhāgavata scan may be partial; Hebrew, Greek and Devanagari come through as noise in several scans. Two scans that came out as Devanagari OCR noise (`x-bvp`, `x-bks`) were replaced by better ones before being kept.')
A('10. **A further round of open translations** (16 November 2026, on the maker’s instruction “keep going and find more texts”): 128 texts, 142 MB of text files, found by searching the Internet Archive and Project Gutenberg and built by `tools/texts_ancient.py`, `texts_abrahamic.py`, `texts_christian.py`, `texts_asia.py` and `texts_peoples.py`. **Egypt, Mesopotamia and Persia:** Breasted’s Ancient Records of Egypt (volumes 1–4), Erman’s Literature of the Ancient Egyptians, Budge’s Egyptian Heaven and Hell (the Amduat and the Book of Gates), Legends of the Gods, Osiris, Gods of the Egyptians and the fuller Theban Book of the Dead, the tales of Petrie, Maspero and Griffith, Cory’s fragments of Berossus and Manetho; Harper, Rogers, King, Thompson, Langdon and Barton for Babylonian and Sumerian texts and Jastrow’s study of the Babylonian Job; the Book of Arda Viraf and the Dabistan. **Greece and Rome:** Plutarch’s Morals (with Isis and Osiris and the Delphic essays), Cicero on the gods and divination, Ovid’s Fasti, Pausanias and Lang’s Homeric Hymns. **Gnostics and Mandaeans:** Mead’s Fragments of a Faith Forgotten and his selections from the Mandaean John-Book. **Jewish:** Ginzberg’s Legends of the Jews (volumes 1–4), Pirke de-Rabbi Eliezer, the Kuzari, a selection from Duties of the Heart, the Guide for the Perplexed, Singer’s Prayer Book and the festival machzor (Service of the Synagogue), Etheridge’s Targums (Leviticus to Deuteronomy), Taylor’s Pirqe Aboth and the Book of Jasher. **Islam and Bahá’í:** the Shia Hayat al-Qulub, the Muharram passion play, al-Ghazali’s Confessions, Nawawi’s Minhaj (Shafi’i law) and al-Biruni’s Chronology of Ancient Nations; and the Bahá’í works first printed in English before 1931 (Some Answered Questions, the Seven Valleys, Talks in Paris, the Promulgation of Universal Peace, the Tablets of Abdul-Baha Abbas, the Traveller’s Narrative). **Christian classics:** Aquinas’s Summa Theologica and Summa contra Gentiles (Books One to Three), Anselm, Boethius, Pseudo-Dionysius, the Little Flowers, Catherine of Siena, Angela of Foligno, Theologia Germanica, the Imitation of Christ, Teresa, John of the Cross, Ignatius, Francis de Sales, Brother Lawrence, Pascal, the Roman Breviary, the Roman Missal for the laity, the Sarum Missal, Hapgood’s Orthodox Service Book, Calvin’s Institutes, Schaff’s Creeds of Christendom, the Book of Concord, the decrees and catechism of Trent, Luther’s Table Talk and Bondage of the Will, Foxe, Law, Taylor, Andrewes and Wesley, and a few Syriac, Ethiopic and Chinese Christian texts. (Dante and Bunyan are in the imagined shelf, not here.) **India, Buddhist Asia, Jain and China:** the Yoga Vasishtha, Nyaya Sutras, Vivekachudamani, Panchadashi, Mahanirvana Tantra, Serpent Power, the Aitareya Brahmana, Keith’s Rigveda Brahmanas, the Nirukta, the Gita Govinda, Alberuni’s India and the Siva-Gnana-Botham; Xuanzang, Faxian, I-Tsing, the Shikshasamuccaya, the Lalita Vistara, Ashoka’s edicts and Beal’s Catena; the Jain Samayasara and Gommatasara; Wang Yangming, Zhu Xi, the I-li, the Kan-ying p’ien and A Mission to Heaven. **Peoples:** Brinton’s Aztec hymns, Cakchiquel Annals, Maya Chronicles and Lenape legends, Markham’s Inca narratives, Malo’s Hawaiian Antiquities, Barton’s Ifugao Law, and the Australian field records of Howitt, Spencer and Gillen and Langloh Parker. **How these were built:** as in the round before, plus a new opt-in `trim_back` (publishers’ advertisements, library stamps and, where the page references are plainly dense, a trailing index). **What is rough:** Sanskrit, Greek, Hebrew, cuneiform, Ethiopic and Nahuatl come through as noise (King, Thompson, Langdon, Barton, Budge’s Miracles of Mary and Lives of Mabâ’ Seyôn, Brinton); some texts still end in an index or a glossary; Breasted’s fifth volume (the index) and Ginzberg’s notes volumes are left out; the Etheridge scan is Leviticus to Deuteronomy only; Duties of the Heart is a short selection; Alberuni’s volume 2 and Plutarch’s fourth volume came from different scans; several translators died after 1955 (Blackman, Suzuki, Madhavananda, Saeki), so their English may still be protected in some countries. **Left out on purpose:** the Bahá’í texts on Project Gutenberg, because their files carry the Bahá’í International Community’s terms of use and most are later translations; Pines’s Guide for the Perplexed (1963).')
A('11. **A sixth batch of open translations** (16 November 2026, on the maker’s instruction “keep going and find more texts”): 58 texts, 43 MB of text files, built by `tools/texts_round6.py` from the Internet Archive and Project Gutenberg. **Modern and revival movements:** the Book of Mormon (1830 text) and the Doctrine and Covenants, Science and Health, Ellen White’s Great Controversy and Steps to Christ, the Holy Piby, Barclay’s Apology, Woolman’s Journal and Penn’s No Cross, No Crown, and Müller’s Ramakrishna. **Medieval and Reformation Christian:** Tauler, Ruysbroeck, Hilton, Rolle, Suso, Bernard (two volumes), the Golden Legend (a selection), Bede’s Ecclesiastical History, Gregory’s Dialogues, Luther’s 95 Theses and three primary works, Zwingli, the Martyrs Mirror, the 1549 Book of Common Prayer and the Hymns of the Russian Church. **Jewish:** Hebrew Ethical Wills, the Kitzur Shulchan Aruch (Goldin), the Eight Chapters of Maimonides, the Union Haggadah and Polano’s Selections from the Talmud. **Islam:** Gulshan-i Raz, Lawa’ih, the Tarjuman al-Ashwaq, Nicholson’s selected poems of Rumi, Lane-Poole’s Speeches and Table-Talk of the Prophet and Hayy ibn Yaqzan. **India, Buddhist Asia and China:** Hume’s Thirteen Principal Upanishads, Vivekananda’s Raja, Jnana and Bhakti Yoga, the Sarva-Darsana-Samgraha, the Vedantasara, the Kathavatthu (Points of Controversy), Shinran’s Buddhist Psalms, Soyen Shaku’s Sermons and Carus’s Tao-teh-king. **Greece, Rome and the North:** Iamblichus on the Mysteries, Lucian’s Syrian Goddess, the Bacchae, Lucretius, the Volsunga Saga, the Four Ancient Books of Wales, the Voyage of Bran, Silva Gadelica (the English volume) and Gods and Fighting Men. **Peoples:** Rattray’s Ashanti, Shortland’s Maori Religion and Mythology, Boas’s Tsimshian Mythology, Fletcher’s Hako. **Found already in the folder and left out:** the Spirits’ Book, Swedenborg’s Heaven and Hell, Ralston’s Tibetan Tales, Giles’s Chuang Tzu, Spence’s Popol Vuh, Soothill’s Lotus of the Wonderful Law (`x-ls`) and a second scan of Mooney’s Sacred Formulas of the Cherokees (`a-chsf`), each of which was built once from this batch and then removed when the audit showed the same translation under another id (`v-kard`, `v-heav`, `t-ralst`, `x-zhu`, `x-pop`, `x-ls`, `a-chsf`). **What is rough:** Persian, Arabic, Welsh, Irish and Chinese text comes through as noise in the bilingual editions; several books still end with an index or an advertisement; the Hebrew Ethical Wills and Gulshan-i Raz scans end in noise; the Golden Legend and Zwingli are selections.')
A('12. **A seventh batch: the second sweep of the Atlas** (16 November 2026; specified by the session that checked the Atlas timeline for traditions with nothing readable, in `tools/texts_gaps2.py`, and built here): 62 texts, 43 MB, with Lady Gregory’s Gods and Fighting Men moved to its typed Gutenberg copy. **Movements:** the Pearl of Great Price, Russell’s Studies in the Scriptures (series 1), the Shakers’ Testimonies of Mother Ann Lee, Menno Simons’s Complete Works, Marcus Garvey’s Philosophy and Opinions, Comte’s Catechism of Positive Religion, Paine’s Age of Reason, Hume’s Dialogues, Feuerbach’s Essence of Christianity, two works of Nietzsche and three of Rudolf Steiner. **Christian and Jewish:** Forbes Robinson’s Coptic Apocryphal Gospels, the Paulician Key of Truth, Schleiermacher’s On Religion, the Samaritan Book of Joshua and the Elephantine papyri. **Persia, India and Buddhism:** the Yezidi sacred books, FitzGerald’s Rubáiyát, Tagore’s Gitanjali and Sadhana, the Psalms of the Maratha saints, the Alvars, the Tamil Saivite saints, the Light of Asia, the Gospel of Buddha, the Buddhist Catechism, the Jatakamala, the Tannisho and the Sacred Edict. **Egypt, Greece, the North and the Celts:** Budge’s Egyptian Magic, Porphyry, Cumont’s Mysteries of Mithra, the Golden Verses of Pythagoras, Saxo’s Danish History, Heimskringla, Cuchulain of Muirthemne and Barddas. **Peoples:** Scheffer’s Lapland, Ellis on the Ewe and the Tshi, Junod’s Thonga, Smith and Dale’s Ila, Rattray’s Ashanti Proverbs, Burton’s Mission to Gelele, the Code of Handsome Lake, Hale’s Iroquois Book of Rites, Eastman, Curtis’s Indians’ Book, Matthews’s Night Chant, Dorsey’s Siouan Cults, Hoffman’s Midewiwin, Mooney’s Cherokee Formulas, Gill, Fornander (two works), Nelson and Boas on the Eskimo, Williams’s Fiji and Seabrook’s Magic Island. **Left out by the session that specified it:** Bahá’u’lláh’s Hidden Words on Gutenberg (terms forbid modification), the Desatir, Handy’s Polynesian Religion, Budge’s Coptic Martyrdoms, Rattray’s Akan-Ashanti Folk-Tales, the Kojiki, Satow’s rituals, the Mishkat and the Platform Sutra. **Rough:** the Rubáiyát is cut into one section per stanza; several books end with an index or an advertisement; Sanskrit, Tamil, Greek, Hebrew and Welsh come through as noise in some scans; Scheffer, Burton and Fiji are travellers’ and missionaries’ accounts of peoples, to be read critically.')
A('13. **An eighth batch of open translations** (16 November 2026, on the maker’s instruction “keep going and find more texts”): 23 texts, 12 MB, built by `tools/texts_round8.py` from the Internet Archive and Project Gutenberg. **American revival and the new movements:** Finney’s Lectures on Revivals of Religion, Jonathan Edwards’s Selected Sermons (with Sinners in the Hands of an Angry God), his Religious Affections and Brainerd’s Life, Channing’s Unitarian Christianity, Bucke’s Cosmic Consciousness, Collins’s Light on the Path, Trine’s In Tune with the Infinite, Ouspensky’s Tertium Organum and Tolstoy’s Letter to a Hindu. **Christian classics and mystics:** Bunyan’s Grace Abounding, Newman’s Apologia, Butler’s Analogy of Religion, Nicholas of Cusa’s Vision of God, Ramon Lull’s Book of the Lover and the Beloved, Molinos’s Spiritual Guide, Madame Guyon’s Autobiography and Fénelon’s Spiritual Letters to Women. **Humanists on religion and conscience:** Erasmus’s Praise of Folly and Enchiridion, More’s Utopia and Tolstoy’s Kingdom of God Is Within You and My Confession, My Religion. Searched for and left out: Donne’s Devotions (the Project Gutenberg copy is a 1959 edition), Guyon’s Short and Easy Method (the scans carry a running head on every page), Kautilya’s Arthashastra (a work of statecraft; the scan begins mid-book) and Jung’s Psychology of the Unconscious (psychology, not a religious text).')
A('14. **A ninth batch: the study of religion and its reference works** (16 November 2026, on the maker’s instruction “keep going and find more texts” and “worry about a complete product”): 108 texts, about 320 MB, built by `tools/texts_round9.py`, all in the shelf-only Scholarship group. **The classics of the study of religion:** Tylor’s Primitive Culture, Robertson Smith’s Religion of the Semites, Harrison’s Prolegomena and Themis, Frazer’s Belief in Immortality (three volumes), Max Müller’s five books of lectures, Lang, Marett, Jevons, Tiele, Otto, Freud’s Totem and Taboo and Future of an Illusion, Weber’s Protestant Ethic, Wellhausen, Schweitzer, Harnack and Renan (Durkheim’s Elementary Forms, James’s Varieties and Ginsburg’s Kabbalah were already in the folder as z-dur, z-jam and z-gin). **The religions of the world:** Kern, Barth, Monier-Williams (two books), Hopkins, Macdonell, Keith, Eliot (three volumes), de Groot (six volumes), Giles, Legge, Edkins, Griffis, Aston, Hearn, Jackson, Moulton, Macdonald, Nicholson, Erman, Jastrow, Farnell (five volumes), Murray, Rohde, Fowler, Glover, Cumont, Breasted, Legge’s Forerunners, Angus, Schürer (five volumes), Schechter, Moore, Edersheim, and ten volumes of the Mythology of All Races (the others are a-ocea, or were published after 1930). **Reference works, one text per printed volume:** Hastings’s Encyclopaedia of Religion and Ethics (twelve volumes and the index), the Jewish Encyclopedia (twelve), the Catholic Encyclopedia (fifteen and the index) and Hughes’s Dictionary of Islam; each volume is cut into parts of about 28,000 letters named by their first headword. Duplicates found and dropped: Budge’s Gods of the Egyptians (x-goe) and the Oceanic volume (a-ocea).')
A('15. **A tenth batch: the Bible and Christian reference works, the histories of the Church, and more field records** (16 November 2026, on the maker’s instruction “continue”): 52 texts, about 190 MB, built by `tools/texts_round10.py`. **Dictionaries, one text per printed volume (shelf-only Scholarship group):** Hastings’s Dictionary of the Bible (four volumes and the Extra Volume), the Encyclopaedia Biblica (four), the Dictionaries of Christ and the Gospels (two) and of the Apostolic Church (two), the Dictionary of Christian Biography (volumes 1, 3 and 4; volume 2 has no readable scan), the Dictionary of Christian Antiquities (two), Julian’s Dictionary of Hymnology (two) and Benham’s Dictionary of Religion. **Histories:** Schaff’s History of the Christian Church (eight volumes) and Harnack’s History of Dogma (seven). **Comparative religion:** Frazer’s Totemism and Exogamy (four volumes), Folk-Lore in the Old Testament (three), Adonis, Attis, Osiris and The Worship of Nature, Hartland’s Legend of Perseus (three) and Primitive Paternity (two), Kuenen’s Religion of Israel (three), and Frazer’s translation of Apollodorus (Greece and Rome). **Field records (tribal shelf):** Crooke on northern India, Roscoe’s Baganda and Northern Bantu, Hose and McDougall on Borneo, Skeat and Blagden on the Malay Peninsula, Seligmann on New Guinea, Rivers’s Todas, Frobenius’s Voice of Africa, Thurston’s Omens and Superstitions, Hollis’s Masai and Nandi, Bogoras’s Yukaghir tales and Swanton’s Haida and Tlingit texts. Dropped as duplicates after the dup-scan: Mooney’s Ghost-Dance Religion (a-ghos) and a scan of volume 2 of the Dictionary of Christian Antiquities that had been taken for the Dictionary of Christian Biography. Fewkes’s Hopi Katcinas and Dorsey’s Cheyenne Sun Dance were left out at first under a rule on sacred material that was never the maker’s and was withdrawn on 17 November 2026; both are in (items 27 and 28).')
A('16. **An eleventh batch: the Canaanites, the Phoenicians and early Arabia** (16 November 2026, on the maker’s words “dont leave out the canaanites either”): 18 texts, about 17 MB, built by `tools/texts_round11.py`. **Canaan, Phoenicia and Carthage:** Cooke’s Text-Book of North-Semitic Inscriptions (the Moabite Stone, the Phoenician royal and Punic dedications, the Marseilles tariff, Aramaic, Nabataean and Palmyrene, with English translations), Petrie’s translations of the Canaanite kings’ Amarna letters, Luckenbill’s Assyrian royal inscriptions, MacDonald’s Marseilles and Carthage sacrifice tablets, Rawlinson’s History of Phoenicia, Macalister’s Gezer and The Philistines, Stanley Cook’s Religion of Ancient Palestine in the Second Millennium B.C., Barton’s Archaeology and the Bible and Sketch of Semitic Origins, Jeremias, and Garstang’s Hittite Empire. **Arabia before Muhammad (a Path station that had no reading):** Lyall’s Translations of Ancient Arabian Poetry and Clouston’s Arabian Poetry for English Readers, with Robertson Smith’s Kinship and Marriage in Early Arabia, Zwemer, Nicholson’s Literary History of the Arabs and Doughty’s Travels in Arabia Deserta. **What cannot be added:** the Ugaritic tablets themselves (the Baal Cycle, Kirta, Aqhat, the Rapi’uma texts) were found at Ras Shamra in 1929 and first printed in French in 1929–31; every English translation of them is later than 1930 and in copyright, so the Library’s Baal Cycle entry (x-bal) stays a catalogue entry. The Mesha Stele, the Marseilles Tariff, the Nabataean inscriptions and Sanchuniathon are now covered through x-cns, x-mst and Cory’s Ancient Fragments (x-cor); the Pyrgi tablets (found in 1964) have no public-domain translation.')
A('17. **A twelfth batch, from an assessment of what the Atlas lists and the Library did not read** (16 November 2026, on the maker’s words “run an assessment and see if we’re missing any religions or offshoots or examples for those religions or how they’re connected”; the report is `COVERAGE_ASSESSMENT.md`, the per-tradition figures `COVERAGE_BY_TRADITION.csv`, both made by `tools/assess_coverage.py`): 76 texts, about 78 MB, built by `tools/texts_round12.py`. **Dissent and reform in Christianity and Judaism:** Lea’s History of the Inquisition of the Middle Ages (three volumes: the Cathars, Waldensians, Spiritual Franciscans and Templars), Comba’s History of the Waldenses, Workman’s John Wyclif, the Letters of John Hus, Conybeare’s Russian Dissenters, Maude’s The Doukhobors, Neatby’s History of the Plymouth Brethren, Booth’s In Darkest England, the Westminster Confession, the Racovian Catechism, Arndt’s True Christianity, Herford’s What the World Owes to the Pharisees and Graetz’s six-volume History of the Jews. **Islam and Iran:** Dhalla’s Zoroastrian Theology, Browne’s Literary History of Persia (three volumes) and Materials for the Study of the Babi Religion, Hitti on the Druze, Brown’s The Dervishes, the Ain-i Akbari (volumes I and III) and the Awarif al-Maarif. **India, Tibet and Japan:** Farquhar’s Modern Religious Movements in India, Bhandarkar’s Vaisnavism and Saivism, Waddell’s Buddhism of Tibet, Francke’s Antiquities of Indian Tibet, Bell’s People of Tibet, Suzuki’s Outlines of Mahayana, Studies in the Lankavatara and Essays in Zen, Anesaki’s Nichiren. **New and secular movements:** Oahspe (volume 1 of the seven-volume reprint only: the other six are not among the open scans), the Aquarian Gospel, Rutherford’s Harp of God, Thomas’s Elpis Israel (the Christadelphians), Ingersoll, Holyoake and Haeckel. **The ancient world:** Showerman’s Great Mother of the Gods, Nilsson’s Minoan-Mycenaean Religion, Evans’s Palace of Minos (volume I), Tacitus’s Germania and Herodotus (Cary’s translation). **Field records for the peoples of Africa, Asia, the Pacific and North America:** the Ainu, Kikuyu, Ibibio, Igbo, Sotho, Khoikhoi, Shilluk, Mende, Dahomey, Kongo, Malagasy and Guanche; the Bagobo, Dusun and Torres Strait Islanders; Tonga, Samoa and the New Hebrides; the mounds of the Ohio valley, Tecumseh and the Prophet, the Californian peoples, the Creek and the Apache; the Munda, Kachari, Khasi, Meitei, Oraon, the Kafirs of the Hindu Kush and the tribes of the Central Provinces; and Puckett’s Folk Beliefs of the Southern Negro. Found to be duplicates and not added: none (the dup-scan found nothing new). **Repairs after reading the built texts:** contents lists, advertisements, library stamps and indexes were cut from the ends of about twenty scans with a new `cut_tail` / `cut_head` option in `tools/texts_archive.py`, and four books whose running heads the splitter had taken for chapter headings (Browne’s Babi Materials, Bhandarkar, Waddell, Bell) are cut into plain parts. Left out on purpose: Lumholtz’s Symbolism of the Huichol Indians and Densmore’s Chippewa Music (the sacred symbols and songs of living peoples), the Nusayri secret books, and the Ugaritic tablets.')
A('18. **A thirteenth batch: more field records, from the same assessment** (16 November 2026): 28 texts, about 42 MB, built by `tools/texts_round13.py`. **Africa:** Kingsley’s West African Studies, Johnson’s History of the Yorubas, Dennett’s Nigerian Studies, Tremearne’s Ban of the Bori (the Hausa spirit religion), Meek’s Northern Tribes of Nigeria, Lindblom’s Akamba, Driberg’s Lango, Bentley’s Pioneering on the Congo, Kidd’s Essential Kafir and Stow’s Native Races of South Africa. **The Pacific:** Ellis’s Polynesian Researches, Rivers’s History of Melanesian Society, Routledge on Easter Island, Brewster’s Hill Tribes of Fiji. **Southeast Asia:** Shway Yoe’s The Burman (the nat spirits), Young’s Kingdom of the Yellow Robe (Thailand), Ling Roth’s Natives of Sarawak and Radcliffe-Brown’s Andaman Islanders. **South Asia:** Roy’s Oraons, Hodson’s Naga Tribes of Manipur, Hutton’s Angami and Sema Nagas, Mills’s Lhota Nagas and the Seligmans’ Veddas. **The Arctic and North America:** Rink’s Tales and Traditions of the Eskimo, Rasmussen’s Across Arctic America, Bancroft’s Native Races (volume III) and Hodge’s Handbook of American Indians (two parts, 11 MB). Not added because the Library already has them: Malo’s Hawaiian Antiquities, Czaplicka, Bleek and Lloyd, Nelson and Boas on the Eskimo, Bompas, Garcilaso and Molina. Three books were cut into plain parts because the splitter took repeated headings for chapters (Johnson, Lindblom, Rink).')
A('19. **A fourteenth batch, for the thinnest families of the assessment** (16 November 2026, on the maker’s “yes, round 14”): 49 texts, about 36 MB, built by `tools/texts_round14.py`. **Southeast Asia:** Marsden’s History of Sumatra, Raffles’s History of Java (volume II only: the scan of volume I was not found), Crawfurd’s History of the Indian Archipelago (three volumes), Jenks on the Bontoc Igorot, Cole on the Tinguian and the Traditions of the Tinguian, Kroeber’s Peoples of the Philippines, Worcester, St John’s Life in the Forests of the Far East, Mouhot’s Travels in Indo-China (Cambodia and Angkor), Fielding-Hall’s Soul of a People, Marshall on the Karen and Mrs. Milne’s Shans at Home. **Inner and East Asia:** Huc and Gabet’s Travels in Tartary, Thibet and China, Rockhill’s Land of the Lamas, Ossendowski’s Beasts, Men and Gods (its truth has been disputed; the note says so), Carruthers’s Unknown Mongolia, Das’s Journey to Lhasa, Czaplicka’s Turks of Central Asia, Vámbéry’s Sketches of Central Asia, Kennan’s Tent Life in Siberia, Clarke on the Miao and Lolo, Hulbert’s Passing of Korea, Gale’s Korea in Transition, Dennys’s Folk-Lore of China and Doolittle’s Social Life of the Chinese. **The Caribbean, Surinam and Guiana (the Afro-diasporic religions):** St John’s Hayti (hostile, and with the cannibalism charge), Léger’s answer, Hearn in Martinique, Beckwith’s Black Roadways (Jamaica), Bryan Edwards on Obeah (volume II), Stedman’s Narrative of the Surinam Maroons and Roth on the Guiana Indians. **The sects of India and the schools of Japan:** Wilson’s Essays on the Religion of the Hindus, Westcott’s Kabir and the Kabir Panth, the History of the Maharajas (the Pushtimarg), Stevenson’s Heart of Jainism and Jaini’s Outlines of Jainism, Sen’s Chaitanya and his Age, Farquhar’s Outline of the Religious Literature of India, the Radhasoami Discourses, Reischauer, Lloyd and Anesaki on Japanese Buddhism and religion, Holtom’s Japanese Enthronement Ceremonies, Underwood’s Religions of Eastern Asia and three books of Brinton’s on American religions. Not added: R. C. Temple’s Thirty-Seven Nats (the one scan has 34,000 letters of a 300-page book), the Royal Parchment Scroll of Black Supremacy (the scan is a garbled library reprint), Cable (no voodoo chapter found), and what the Library already had (Edkins, Griffis, Hearn’s Japan, Barton’s Ifugao Law). The long-s repair for the 18th-century books (Marsden, Edwards, Stedman, Raffles) is partial: it mends only words that are not words and that one letter would make common.')
A('20. **A fifteenth batch: the Andes, the Amazon and the African peoples with no field record yet** (16 November 2026, on the maker’s “yes, round 15” and “don’t be afraid to continue on your own, let’s get as close as we can to covering all the religions”): 34 texts, about 35 MB, built by `tools/texts_round15.py`. **The Andes and Mexico:** Cieza de León’s Travels, Squier’s Peru, Bingham, Bandelier on Titicaca and the Inca, Joyce’s South American and Mexican archaeology, Bancroft’s civilized nations of Mexico and Central America, Starr. **The Mapuche, the Chaco and the Amazon:** Smith and Molina on the Araucanians, Dobrizhoffer’s Account of the Abipones, Grubb among the Chaco peoples, Wallace, Spruce, Whiffen’s North-West Amazonas, im Thurn and Brett on the Indians of Guiana. **Africa:** Schweinfurth and Lloyd on the Dinka and the pygmies, Du Chaillu’s Equatorial Africa (the Fang), Roth’s Benin and Talbot’s Southern Nigeria, Roscoe’s Banyoro and Banyankole, Torday on the Kuba, Rattray’s Chinyanja folk-lore, Hobley on the Luo, Harris’s Highlands of Aethiopia (the Oromo), Westermarck’s Ritual and Belief in Morocco (volume II only) and Bates’s Libyans, and Park and Caillié on the Mande. Not added: Macdonald’s Africana (the one scan is volume II), Westermarck’s volume I (both scans found were volume II), Bates’s Naturalist on the River Amazons and Humboldt’s Personal Narrative (little on religion for their length).')
A('21. **A sixteenth batch: the denominations and orders of the Abrahamic religions** (17 November 2026, continuing the same instruction): 51 texts, about 48 MB, built by `tools/texts_round16.py`. **The Eastern Churches:** Fortescue on the Lesser Eastern Churches and the Orthodox Eastern Church, Adeney, Butler on the Coptic churches, Etheridge on the Syrian churches, Buchanan’s Christian Researches in Asia and the Ethiopian Church. **Protestants and the American communities:** the Baptists, Congregationalists, Moravians, Mennonites and Irvingites, the Harmonists, Zoar, Amana, Oneida and the Shakers, Transcendentalism and Ethical Culture. **Judaism:** Philipson’s Reform Movement, Kohler, Schechter’s Seminary Addresses, Hirsch, Finn’s Jews of Kaifeng and Flad on the Falashas. **Islam:** the Wahhabis, the Indian Wahhabis, the Mahdi (Ohrwalder, Wingate, Slatin, labelled as the Mahdi’s own witnesses), the Ibadi imams of Oman, Hammer’s History of the Assassins, the Zaydi of Yemen and the Ahl-e Haqq. **India, the Pacific and the Mediterranean:** the Sikhs, the Chamars, Nepal and Assam (Hodgson, Gait), the Pacific (Melville, Handy, Thomson, Turner, Christian, Cowan), the Etruscans and Malta. **One text was removed on 17 November 2026:** `x-ahm`, Mirza Ghulam Ahmad’s Philosophy of the Teachings of Islam. The only scan found was the 2010–11 reprint of Sir Muhammad Zafrulla Khan’s 1979 translation, which is in copyright (the scan’s catalogue date of 1905 was the date of the Urdu original). It is replaced by the 1910 English translation (round 19). A scan of every text added since round 12 was made for ISBNs, copyright notices and reprint dates in the first and last pages; no other modern edition turned up (the Gutenberg and Motilal Banarsidass reprints of older books carry reprint notices only). Not added: Burkitt’s Religion of the Manichees (the one scan is a 31,000-letter extract) and Rose’s Glossary of the Tribes and Castes of the Punjab (three volumes of reference, kept for later).')
A('22. **A seventeenth batch: the sects of India, Buddhism’s history and schools, the Slavs, the Iroquois and the archaeology of the mounds** (17 November 2026): 24 texts, about 20 MB, built by `tools/texts_round17.py`. **India:** Oman’s Mystics, Ascetics and Saints of India, Bhattacharya’s Hindu Castes and Sects, Whitehead’s Village Gods of South India, Elmore’s Dravidian Gods, Stevenson’s Rites of the Twice-Born, Heber’s Narrative of a Journey through the Upper Provinces. **Buddhism:** Pratt’s Pilgrimage of Buddhism, Getty’s Gods of Northern Buddhism, Johnston, Soothill, Hackmann, Saunders’s Epochs in Buddhist History, Nanjio’s Twelve Japanese Buddhist Sects and Copleston’s Buddhism. **The Circassians, the Slavs and others:** Bell’s Circassia, Ralston’s Songs of the Russian People, Morgan’s League of the Iroquois, Wafer’s New Voyage (the Cuna of Darien). **The archaeology of Mexico and the North American mounds:** Spinden, Joyce’s Mexican Archaeology, Thomas’s Mound Explorations, Shetrone’s Mound-Builders and Thruston’s Antiquities of Tennessee. Not added because the Library has them: Cumont’s Oriental Religions, Mead’s Fragments of a Faith Forgotten, Hale’s Iroquois Book of Rites. Indexes and catalogue cards were cut from the ends of seven scans after the first build.')
A('23. **An eighteenth batch: China and Korea, the Pacific, and southern, central and eastern Africa** (17 November 2026): 20 texts, about 18 MB, built by `tools/texts_round18.py`. **China and Korea:** Lindley’s Ti-ping Tien-kwoh and Meadows’s The Chinese and their Rebellions (the Taiping and the God-Worshipping Society), de Groot’s Sectarianism and Religious Persecution in China (the White Lotus, Wu-wei and Xiantian sects), McKenzie’s Tragedy of Korea (the Tonghak) and Griffis’s Corea, the Hermit Nation. **The Pacific:** Malinowski’s Argonauts of the Western Pacific, Guppy’s Solomon Islands and Christie’s Subanuns of Sindangan Bay. **Africa:** Livingstone’s Missionary Travels, Moffat’s Missionary Labours, Arbousset and Daumas, Grout’s Zulu-Land, Shooter’s Kafirs of Natal, Galton and Andersson (Damaraland and Ovamboland), Krapf’s Travels in Eastern Africa (the Wanika and the Oromo), Cameron’s Across Africa and Bent’s Ruined Cities of Mashonaland. **Religious Science and the American Southwest:** Holmes’s Creative Mind (1919) and Kidder’s Southwestern Archaeology. Not added: Crowley’s Magick (the one scan is lending-only), the Equinox (the scan found is a modern typeset reprint) and Best’s and Woodford’s books (no scan found). Nine scans had their indexes, appendices of tables and printers’ lines cut after the first build, because the scan’s cleaning removes an index’s heading; each cut starts at the index’s first entry (`cut_tail`, now with an optional `cut_tail_from` for an index that starts before the last 40% of a volume).')
A('24. **A nineteenth batch: the movements that the assessment and a mention-scan of the Library still found without an example** (17 November 2026): 29 texts, about 23 MB, built by `tools/texts_round19.py`. **Judaism and Christian movements:** Dubnow’s three-volume History of the Jews in Russia and Poland (Hasidism with its Chabad and Bratslav courts, the Sabbatean and Frankist movements), Miller’s Evidence from Scripture and Bliss’s Memoirs of William Miller (the Millerites), Palmer’s Way of Holiness, Campbell’s Christian System (the Restoration movement), Ballou’s Treatise on Atonement (Universalism), Neale’s History of the So-Called Jansenist Church of Holland (the Old Catholic Church of Utrecht), Rae’s Syrian Church in India (the Thomas Christians and the Reformed Syrian Church), Cary’s History of Christianity in Japan: Protestant Missions (volume I, with the hidden Christians, is lending-only), Laubach’s People of the Philippines, Sabatier’s Life of St Francis and Aulard’s Christianity and the French Revolution (the worship of Reason, the Supreme Being, Theophilanthropy). **Esoteric currents, Sufism in the West and the Ahmadiyya:** Waite’s Brotherhood of the Rosy Cross, Inayat Khan’s Sufi Message of Spiritual Liberty (1914), Bailey’s Initiation, Human and Solar (1922), Ha’nish’s Inner Studies (Mazdaznan), Mirza Ghulam Ahmad’s Teachings of Islam (the 1910 translation; the scan is the 1987 reprint of it, which replaces the removed x-ahm), Kamal-ud-Din’s Ideal Prophet and the Moorish Science Temple’s Holy Koran (1927), each labelled as the movement’s own book. **The deep past and China:** Munro’s Prehistoric Japan (Jōmon), Fergusson’s Rude Stone Monuments, Schrader’s Prehistoric Antiquities of the Aryan Peoples (the reconstruction of Indo-European culture and religion), Hirth’s Ancient History of China (the Shang) and Williams’s Middle Kingdom (two volumes), and Bretschneider’s Mediaeval Researches, volume I (the Taoist master Ch’ang Ch’un and the Quanzhen school). **The Americas:** Lummis’s Land of Poco Tiempo (the Pueblos and Penitentes), Lumholtz’s Unknown Mexico (two volumes) and Symbolism of the Huichol Indians, and Spier’s Sun Dance of the Plains Indians. Not added: Crowley’s Book of the Law, Equinox and Magick (the scans found are modern reprints or lending-only), Roerich’s Agni Yoga, Best’s Maori books, the Vailala Madness report, Cowan’s volume II (Te Kooti and Parihaka: no text layer), Bent’s Southern Arabia (the Library already has it as x-bnt) and Fortier’s Louisiana Studies and Hearn’s Creole Sketches (no voodoo chapter).')
A('25. **A twentieth batch, and a way to count the books the Library already had** (17 November 2026): 3 texts, about 3 MB, built by `tools/texts_round20.py`: Hasluck’s Christianity and Islam under the Sultans (the Bektashi and the Kizilbash or Alevi; volume II is the 1929 text from a second scan, because the first was unreadable), Lyde’s Asian Mystery (the Nusairis, now Alawites) and Sarda’s Ajmer: Historical and Descriptive (the dargah of Khwaja Muinuddin Chishti). **The mention scan:** `tools/library_about.json` now also links about a hundred books the Library already held to the Atlas traditions they are about, found by counting the names of each still-uncovered tradition in every text (for example Athanasius and Schaff on Arianism, Tertullian on Marcion, Augustine on the Donatists and Manichaeans, the Encyclopaedia of Religion and Ethics on the Ajivikas, Druids, Nusairis and Bene Israel, Wingate on the Sanusiyya, Browne’s Literary History of Persia on the Hurufis, the Handbook of American Indians on the Huichol, the Sun Dance and peyote). Each link was read in context before it was added; a name that appears only in passing was left out. **Source lore:** a second file, `tools/library_lore.json`, names the old texts that revived traditions draw on (the Eddas for Heathenry, Homer and Hesiod for Hellenism, the Kalevala for Suomenusko, the Egyptian funerary texts for Kemetism, Ovid’s Fasti and Fowler for Roman reconstructionism, Ralston and the Mythology of All Races for Rodnovery, Barddas for neo-Druidry); `assess_coverage.py` reports them separately and does not count them as examples of the tradition. **An id clash was found and fixed on 17 November 2026** (reported by the Atlas session): round 10 had built Benham’s Dictionary of Religion (1887) under `x-dre`, an id the Library already used for the Dresden Codex (a Maya codex with no English text), so the Dresden Codex entry opened a Christian dictionary. The dictionary is now `x-bnh`, on the study-aid shelf with the other dictionaries of Christian history; `x-dre` is catalogued-only again, and its Journey station has no text to open. A sweep of every built text against its Library title found no other mismatch, and no id is defined in two spec modules.')
A('26. **A twenty-first batch: the ancient Mediterranean and its edges, the Uniate Churches, the Muggletonians, Rizal and a record from Papua** (17 November 2026, continuing the same instruction): 9 texts, 10.6 MB, built by `tools/texts_round21.py`: Ammianus Marcellinus (Yonge’s Bohn translation, 1862), Strabo’s Geography (Hamilton and Falconer, three volumes: Spain, Gaul and the Druids, the Illyrians, Thracians and Dacians, the Black Sea steppe), Caesar’s Gallic War (books I to VII, with the Gauls’ religion in book VI), Evans’s Antiquarian Researches in Illyricum (1883), Fortescue’s Uniate Eastern Churches (the Melkites; the Ruthenians are only mentioned), Reeve and Muggleton’s Works in three volumes (1832), Rizal’s two novels in Derbyshire’s 1912 versions (the Rizalista movements venerate him; he did not claim it) and F. E. Williams’s Orokaiva Society (1930: a book first published in 1930 is in the United States public domain from 1 January 2026). An id clash was found and mended on the way: the Benham dictionary had been built under the Dresden Codex’s id and is now `x-bnh`. Left out: the Loeb Julian (Greek mixed in), Henry’s Ancient Tahiti (no text layer).\n'),
A('27. **A twenty-second batch: outsiders’ records of the ceremonies, societies and sacred songs of living peoples** (17 November 2026, on the maker’s words that the Library is a collection of all human religion and that “the people need all the information available to decide for themselves”): 25 texts, 12.3 MB, built by `tools/texts_round22.py` from government, museum and university publications of 1887–1929: Fewkes on the Hopi katcinas, the Hano solstice altars and the Flute and Snake ceremonies, Stevenson’s Zuñi and Sia, Voth’s Oraibi Powamu, Soyal (with Dorsey) and Marau, Dorsey’s Arapaho Sun Dance and Cheyenne, Wissler’s Blackfoot Sun Dance and Ceremonial Bundles, Lowie’s Crow Sun Dance and Shoshone societies, Skinner’s Menomini medicine ceremony and bundles, Densmore’s Chippewa Music I and II and her Teton Sioux, Mandan and Hidatsa, Pawnee and Papago volumes, Matthews’s Mountain Chant, Boas on the secret societies of the Kwakiutl and Roth’s Queensland records. **The rule that kept such books out** (sacred or restricted material of living peoples) **was never the maker’s** (an earlier assistant’s notes called it “the maker’s rule” and nothing in the conversations supports that) **and was withdrawn on 17 November 2026**. Each book carries a plain label: an outsider’s record, some of it held sacred by the peoples themselves; understood, not endorsed; where the peoples’ own accounts exist, read them as well.\n'),
A('28. **A twenty-third batch: rituals, exposures and the books of secret and initiatory orders** (17 November 2026, on the same words and on the instruction to sort every “left out on purpose” list into rights and the rest, see `LEFT_OUT_SORTED.md`): 22 texts, 10.9 MB, built by `tools/texts_round23.py`: the Masonic exposures (Prichard 1730, *Jachin and Boaz* 1762, *The Three Distinct Knocks*, Morgan 1826, Bernard’s *Light on Masonry* 1829, Allyn’s *Ritual of Freemasonry* with its Royal Arch, Templar and Odd Fellows degrees, Duncan’s *Ritual and Monitor* 1866), the Nauvoo endowment as two who left reported it (Van Dusen 1849; Mary Ettie Smith 1857), the Nusayri (Alawite) secret book in Salisbury’s 1866 notice with long extracts, the *Sixth and Seventh Books of Moses* and Albertus Magnus’s *Egyptian Secrets*, Mead’s *A Mithriac Ritual* and Taylor’s *Eleusinian and Bacchic Mysteries*, Leadbeater’s *Science of the Sacraments* (the Liberal Catholic Mass) and Heindel’s *Rosicrucian Cosmo-Conception*, Owen’s *Old Rabbit, the Voodoo* and Hesketh Prichard’s *Where Black Rules White*, Addison’s *Knights Templars*, Le Plongeon’s *Sacred Mysteries among the Mayas and the Quiches* (labelled a popular claim), and two books once left out by judgment (Jung’s *Psychology of the Unconscious*; Kautilya’s *Arthashastra* in Shamasastry’s translation, from a later Mysore reprint of the third edition of 1929). **Left out, for rights:** the *Equinox* and the *Book of the Law* (O.T.O.’s typeset file that may be copied only unmodified; the 1938 edition with Crowley’s later commentary), Finney’s Freemasonry (a 1999 e-text that forbids change). **Left out, no usable scan:** Crowley’s *Magick* (the Wellcome scan answers 403) and the 1657 *Ars Notoria*. Each exposure’s note says that the fraternity holds the working private, that exposures vary in accuracy and are of their time, and that the Library neither endorses nor judges. Page numbers (`tools/texts_pages.py build`) were rebuilt for the scanned texts.\n'),
A('**Corrections to my own first audit.** Three of its “problems” were wrong and are withdrawn: the Acaranga Sūtra was in its file all along (OCR spelled its name beyond my search pattern); the Khuddaka Nikaya does include some Jātaka tales (one section of selected ones; the other 540-odd are not there); and the Shatapatha Brahmana’s last book (XIV, which holds the Brihadaranyaka Upanishad) is present. The “ten scans open with a library stamp” count was also overstated: most of those openings are real title pages, and only the Indian accession page and a museum stamp were stamps.\n')
A('**Still open.**\n')
A('* **Not in the folder at all:** the Puranas other than the Vishnu, Bhagavata, Devī Bhāgavata, Mārkaṇḍeya, Matsya, Agni, Garuda and the first half of the Brahma-Vaivarta (no open English found for the Padma, Linga, Vāyu, Brahmāṇḍa, Kūrma, Varāha, Vāmana, Nāradīya, Skanda, Bhaviṣya, Śiva or Brahma Purāṇas, or for the Brahma-Vaivarta’s Gaṇapati and Kṛṣṇa-janma khaṇḍas or the Harivaṃśa); the Apadāna and the other Khuddaka books besides the Jātaka, Udāna and the Therīgāthā and Theragāthā; the Vibhaṅga, Dhātukathā, Yamaka and Paṭṭhāna (their English translations are modern and in copyright), so four of the seven Abhidhamma books are still missing; the Chinese and Tibetan Buddhist canon beyond the sutras above; the Dead Sea Scrolls (modern translations only), the Nag Hammadi library, the Mishnah in full, the Soncino Talmud and the Talmud beyond Rodkinson’s tractates, and the Zohar in full; Gregory of Nazianzus (volume 7 of the second Nicene series, whose scans were unreadable here) and Books I and III of Abramelin; the Emerald Tablet and Boehme’s Aurora; the Kojiki, Huainanzi and Tattvartha Sutra; Summa contra Gentiles Book Four; most of the Library’s remaining entries without a file (listed below).')
A('* **Translations are old.** Everything outside the World English Bible and SuttaCentral is a 19th- or early 20th-century translation, because those are the ones that can be copied. Several were written for the translator’s own faith (Rodwell’s 1861 Qur’an in an invented chronological order; Arnold’s 1885 *Song Celestial*; Müller, Legge, Mead). They are public domain, not necessarily the most accurate or the most acceptable to the tradition they translate.')
A('* **Scan quality.** Eighty-odd texts are OCR of scans and carry recognition errors; Sanskrit and Chinese characters often come through as noise (`x-gl`, `x-men`, the Sacred Books of the East volumes). `x-sam` ends with a concordance table, `x-aca` and `x-kalp` keep the translator’s page-heading debris, and the unattributed headings inside some volumes are OCR guesses.')
A('* **Partial by design:** the Guru Granth Sahib entry is Macauliffe’s interpretive rendering with the Gurus’ lives; the Talmud and Zohar are anthologies; `x-herm` is Mead’s studies with his translation.\n')
A('**What is solid.** All 66 Bible books have the right chapter counts and unbroken verse numbers (23,145 Old Testament and 7,958 New Testament verses; the standard English counts are 23,145 and 7,957); the Qur’an has all 114 suras; the Digha (34), Majjhima (152), Samyutta (to 56.131) and Anguttara (to 11.1151) Nikayas run complete; the Mahabharata is Ganguli’s four volumes and ends at Book 18 (the book-by-book count was not checked). Every file’s header agrees with its content.\n')
A('## Same content filed under different names\n')
if dups:
    A('These pairs hold the same text. The title says one thing and the file holds a whole other volume, so a reader opening the second entry gets the first entry’s content.\n')
    A(md_table(['Entries', 'What the file actually is'], [(' = '.join('`%s` %s' % (t, rows[t]['title']) for t in sorted(v)), rows[sorted(v)[0]]['by'][:110]) for v in dups]))
else: A('None: no two files hold the same text. (Four volumes that used to be filed under two names each are now cut into their own entries.)')
other = [(n, a, b) for n, a, b in shared if not any(a in v and b in v for v in dups)]
if other: A('\nPartly shared (long identical passages, by design: a volume’s hymns also appear in the larger collection): ' + '; '.join('%s + %s (%d passages)' % (a, b, n) for n, a, b in other[:12]))
A('\n## Scan quality\n')
A('Each scan text is scored by the share of its words found in a standard English word list (a clean modern text scores about **%.2f** here; Sanskrit, Hebrew and Gaelic names pull a good text lower, so compare scans with each other, not with 1.0). “Bad sections” are sections that score under 0.45, which is what index pages, page-number runs and recognition noise look like.\n' % baseline)
sc = sorted((r for r in rows.values() if r['scan']), key=lambda r: r['score'])
A(md_table(['Text', 'Score', 'Bad sections', 'Opens with junk?'], [('`%s` %s' % (r['id'], r['title'][:50]), '%.2f' % r['score'], '%d of %d' % (r['secs_bad'], r['secs_n']), 'yes: “%s”' % r['first_title'] if r['first_bad'] else 'no') for r in sc[:30]]))
A('\nThe other %d scans score %.2f to %.2f. Full list in the JSON-style table at the end of this file.\n' % (max(0, len(sc) - 30), sc[30]['score'] if len(sc) > 30 else 0, sc[-1]['score']))
A('## Structure checks\n')
A('Bible issues: %s\n' % ('none' if not bible_issues else ''))
for b in bible_issues[:40]: A('* ' + b)
A('\n## Who translated what\n')
A('Every text here is public domain or CC0, which means most translations are 19th- or early 20th-century. Older translators often wrote for their own religion’s readers, paraphrased, or added commentary, and some choices are now disputed. The table is the honest provenance of each non-Bible text.\n')
prov = [(t, rows[t]['title'][:44], rows[t]['by'][:100]) for t in sorted(rows) if not t.startswith(('b-', 'n-', 'd-', 'o-'))]
A(md_table(['Id', 'Title', 'Translation / edition'], prov))
A('\n## Library entries with no file (%d)\n' % len(lib_missing))
A('Counts by Library group: ' + ', '.join('%s %d' % (g, n) for g, n in lib_missing_g.most_common()) + '.\n')
A(md_table(['Id', 'Title', 'When', 'Group'], [(l['id'], l['title'][:70], l['when'], l['group']) for l in lib_missing]))
A('\n## The Atlas catalogue by family group\n')
A(md_table(['Group', 'Records', 'In the folder', 'Library entry, no file', 'No match'], [(g or '(none)', c['records'], c['yes'] + c['yes (part of the work)'] + c['yes (several files)'], c['library entry, no file'], c['no']) for g, c in sorted(by_group.items(), key=lambda kv: -kv[1]['records'])]))
A('\nRecords by status: ' + ', '.join('%s %d' % (k or '?', v) for k, v in st.most_common()) + '.')
A('\n## Aboriginal and Torres Strait Islander records\n')
ab = [c for c in cov if c['tradition'].startswith(('Aboriginal', 'Torres'))]
A(md_table(['Record', 'Tradition', 'Date', 'Status', 'In the folder?'], [(c['title'], c['tradition'], c['date'], c['status'], c['in_folder']) for c in ab]))
